('c4d94d8e-cc24-4c25-8e28-378e60e3fbd5','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Casablanca Heritage Walks SARL','Casablanca Heritage Walks','tour',2,'verified',ARRAY['en','fr','ary-Latn'],'A family-run walking tour company founded in 2009. We specialize in intimate small-group tours of historic quarters, led by licensed local guides who grew up in these streets.',11,96.5,370,4.8,'active'),
('ca04eb61-b8a5-46d1-8e16-f09dc7fd9bf9','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Cultural Tours SARL','Atlas Cultural Tours','tour',3,'verified',ARRAY['en','fr','de'],'Mid-size cultural tour operator with air-conditioned minibuses and university-trained historians. We cover major landmarks with comfortable logistics.',8.8,92.8,251,3.6,'active'),
('41700f8e-a58f-4e1e-95c9-8d51c1ae480f','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Concierge Casablanca SARL','Royal Concierge Casablanca','tour',4,'verified',ARRAY['en','fr','es','it'],'Private luxury touring service with Mercedes vans, art-historian guides, and exclusive access to private palaces and collections not open to the public.',11.3,93.1,347,4.4,'active'),
('311e4177-0c74-417f-bdce-da5826eea48a','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Local Eyes Casablanca SARL','Local Eyes Casablanca','guided_experience',1,'verified',ARRAY['en','fr','ary-Latn'],'A collective of young local guides who show you the real city — hidden cafes, street art, and neighborhoods the guidebooks miss. Pay-what-you-want ethos.',6.3,93.1,196,3.9,'active'),
('91674833-b8c6-4c73-aadb-7f364641b3f3','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',4.3,89.1,290,4.2,'active'),
('2a596d7a-7cfd-4582-b18e-25be68a95909','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',7.7,98,213,3.5,'active'),
('e6467a15-5d0a-485e-a647-054cc111865d','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Casablanca Cooking School SARL','Dar Casablanca Cooking School','workshop',2,'verified',ARRAY['en','fr','ary-Latn'],'A traditional riad kitchen where a local family teaches you to prepare tagine, couscous, and pastries from scratch. Small classes, maximum 6 people.',10.9,96.8,366,3.8,'active'),
('3eef369d-8880-4cba-97cd-c4e0b6720560','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Maison des Artisans SARL','Maison des Artisans','workshop',2,'verified',ARRAY['en','fr','ar'],'A cooperative workshop space where master artisans — potters, leatherworkers, zellige cutters — teach their craft in 2-hour hands-on sessions. Materials included.',4.8,94.8,346,4.8,'active'),
('d3b0d6fa-3e95-4de2-a403-628dbe95ad52','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atelier Lumière SARL','Atelier Lumière','workshop',4,'verified',ARRAY['en','fr','es'],'A luxury creative studio offering private masterclasses with acclaimed Moroccan artists. Photography, calligraphy, and perfume-making in a beautifully restored medina house.',4,88.1,184,5,'active'),
('c727c7ea-aa3c-470a-947e-8cd2f053a158','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Casablanca Budget SARL','Riad Casablanca Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',3.6,98.2,37,5,'active'),
('9d122890-7ce4-449a-a8cf-a56dff8dbae1','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Casablanca Boutique SARL','Dar Casablanca Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',9.2,97.2,55,4.4,'active'),
('5bcd7e49-605e-4663-a5f4-ea33c41d34fb','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Casablanca Royal SARL','Palais Casablanca Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',9.9,98.9,54,4.6,'active'),
('31c88928-881c-4e80-9464-abce86a11c03','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Casablanca Tours SARL','Street Food Casablanca Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',11.2,99,285,3.7,'active'),
('861ddcfd-8476-4816-a71b-14c2005f4ccb','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Casablanca Family Kitchen SARL','Table Casablanca Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',5.9,91.7,333,4.9,'active'),
('828d4a90-2fe5-4f31-b1c8-68d5417b9f0e','MA','a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Casablanca SARL','Le Salon Casablanca','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',0.5,88.4,235,5,'active'),
